import numpy as npimport matplotlib.pyplot as pltimport utildef priorDistribution(beta):    """    Plot the contours of the prior distribution p(a)        Inputs:    ------    beta: hyperparameter in the proir distribution        Outputs: None    -----    """    ### TODO: Write your code here    a0 = np.linspace(-1, 1, 100)    a1 = np.linspace(-1, 1, 100)    A0, A1 = np.meshgrid(a0, a1)    pos = np.dstack((A0, A1))    mu = np.array([0, 0])    Cov = beta * np.eye(2)    inv = np.linalg.inv(Cov)    det = np.linalg.det(Cov)    norm = 1 / (2 * np.pi * np.sqrt(det))    diff = pos - mu    Z = norm * np.exp(-0.5 * np.sum(diff @ inv * diff, axis=2))    plt.figure()    plt.contour(A0, A1, Z)    plt.title("Prior p(a)")    plt.xlabel("a0")    plt.ylabel("a1")    plt.scatter(0.6, 0.8, c='red')    plt.xlim([-1, 1])    plt.ylim([-1, 1])    plt.show()    return    def posteriorDistribution(x,z,beta,sigma2):    """    Plot the contours of the posterior distribution p(a|x,z)        Inputs:    ------    x: inputs from training set    z: targets from traninng set    beta: hyperparameter in the proir distribution    sigma2: variance of Gaussian noise        Outputs:     -----    mu: mean of the posterior distribution p(a|x,z)    Cov: covariance of the posterior distribution p(a|x,z)    """    ### TODO: Write your code here    x = np.array(x)    z = np.array(z)    N = len(x)    # design matrix X = [1, x]    X = np.column_stack((np.ones(N), x))    # posterior covariance    Cov = np.linalg.inv((1/sigma2) * X.T @ X + (1/beta) * np.eye(2))    # posterior mean    mu = (1/sigma2) * Cov @ X.T @ z    # ===== plotting =====    a0 = np.linspace(-1, 1, 100)    a1 = np.linspace(-1, 1, 100)    A0, A1 = np.meshgrid(a0, a1)    pos = np.dstack((A0, A1))    inv = np.linalg.inv(Cov)    det = np.linalg.det(Cov)    norm = 1 / (2 * np.pi * np.sqrt(det))        mu = mu.reshape(2,)    diff = pos - mu    Z = norm * np.exp(-0.5 * np.sum(diff @ inv * diff, axis=2))    plt.figure()    plt.contour(A0, A1, Z)    plt.title(f"Posterior with N={N}")    plt.xlabel("a0")    plt.ylabel("a1")    # true value    plt.scatter(0.6, 0.8, c='red')    plt.xlim([-1, 1])    plt.ylim([-1, 1])    plt.show()    return (mu,Cov)def predictionDistribution(x,beta,sigma2,mu,Cov,x_train,z_train):    """    Make predictions for the inputs in x, and plot the predicted results         Inputs:    ------    x: new inputs    beta: hyperparameter in the proir distribution    sigma2: variance of Gaussian noise    mu: output of posteriorDistribution()    Cov: output of posteriorDistribution()    x_train,z_train: training samples, used for scatter plot        Outputs: None    -----    """    ### TODO: Write your code here    # x = np.array(x)    # # sample mean line    # X_test = np.column_stack((np.ones(len(x)), x))    # #z=a0​+a1​x    # y_mean = X_test @ mu    # plt.figure()    # # training data    # plt.scatter(x_train, z_train, c='blue')    # # predicted line    # plt.plot(x, y_mean, c='black')    # plt.title("Bayesian Linear Regression Prediction")    # plt.xlabel("x")    # plt.ylabel("z")    # plt.show()    x = np.array(x)        means = []    stds = []    for xi in x:        phi = np.array([1, xi])  # shape (2,)        # predictive mean        mean = phi @ mu        # predictive variance        var = sigma2 + phi @ Cov @ phi        means.append(mean)        stds.append(np.sqrt(var))    means = np.array(means)    stds = np.array(stds)    # Plot predictions + uncertainty    plt.figure()    plt.errorbar(x, means, yerr=stds, fmt='b-', label='Prediction')    # Plot training data    plt.scatter(x_train, z_train, color='red', label='Training Data')    plt.xlim([-4, 4])    plt.ylim([-4, 4])    plt.xlabel('x')    plt.ylabel('z')    plt.title('Prediction with Uncertainty')    plt.legend()    plt.show()    return    if __name__ == '__main__':        # training data    x_train, z_train = util.get_data_in_file('training.txt')    # new inputs for prediction     x_test = [x for x in np.arange(-4,4.01,0.2)]        # known parameters     sigma2 = 0.1    beta = 1        # number of training samples used to compute posterior    ns  = 5        # used samples    x = x_train[0:ns]    z = z_train[0:ns]        # prior distribution p(a)    priorDistribution(beta)        # posterior distribution p(a|x,z)    mu, Cov = posteriorDistribution(x,z,beta,sigma2)        # distribution of the prediction    predictionDistribution(x_test,beta,sigma2,mu,Cov,x,z)        